/**
 * The ONE implementation behind every `scripts/bundle-*pubkey.mjs`.
 *
 * Each bundler vendors one Ed25519 public key into a checked-in TypeScript module
 * (`packages/core/src/security/*-pubkey.generated.ts`). Until 2.5.4 there were four
 * hand-copied implementations, and they had drifted:
 *
 *   - every one stamped `new Date().toISOString()` into line 1, so EVERY `npm publish`
 *     (prepublishOnly runs all four) rewrote four tracked files whose key bytes had not
 *     changed. That left the tree dirty after each release, and `sync-public.sh`
 *     correctly refused to mirror it (2.5.3, 2026-11-08);
 *   - two `--check` modes compared "everything except line 1" to dodge the timestamp,
 *     one compared nothing but the fingerprint, and one wrote unconditionally;
 *   - the registry bundler's "no change" branch could never be reached, because a fresh
 *     timestamp always differs from the committed one.
 *
 * So the output is now a pure function of (pem, declaration): identical inputs produce
 * identical bytes, a write happens only when the bytes differ, and `--check` compares
 * the WHOLE file. The key's RAW-bytes sha256 is already in the header, which is the
 * provenance a timestamp only pretended to give.
 *
 * Each bundler keeps what is genuinely per-key: its pem, its output path, its
 * KNOWN fingerprint allowlist (an oracle the verifier trusts, so it is hand-maintained
 * on purpose and never derived from the pem it judges), and its doc block.
 */
import { readFileSync, writeFileSync, existsSync } from 'node:fs';
import { createHash } from 'node:crypto';
import { resolve, dirname } from 'node:path';
import { fileURLToPath, pathToFileURL } from 'node:url';

export const REPO_ROOT = resolve(dirname(fileURLToPath(import.meta.url)), '..', '..');

/** Ed25519 SubjectPublicKeyInfo is a fixed 44-byte DER blob: a 12-byte prefix + 32 raw key bytes (RFC 8410). */
export function parseEd25519SpkiPem(pem) {
  const b64 = pem.split(/\r?\n/).filter((l) => l && !l.startsWith('-----')).join('');
  const der = Buffer.from(b64, 'base64');
  if (der.length !== 44) {
    throw new Error(`Expected 44-byte SubjectPublicKeyInfo blob (Ed25519), got ${der.length} bytes. The pem may be a different key type.`);
  }
  return new Uint8Array(der.subarray(12, 44));
}

export function sha256Hex(bytes) {
  return createHash('sha256').update(bytes).digest('hex');
}

/**
 * Render the generated module for `spec`. Deterministic by construction: nothing here
 * reads a clock, the environment, or the filesystem beyond the pem.
 */
export function renderPubkeyModule(spec) {
  const pem = readFileSync(resolve(REPO_ROOT, spec.pem), 'utf-8');
  const rawBytes = parseEd25519SpkiPem(pem);
  const fingerprint = sha256Hex(rawBytes);
  const known = [...spec.knownFingerprints].sort();
  const header = [
    `// AUTO-GENERATED by ${spec.script}. Deterministic: a pure function of the pem below.`,
    `// Source pem: ${spec.pem}`,
    `// RAW-bytes sha256: ${fingerprint}`,
    `// DO NOT EDIT — regenerate via \`node ${spec.script}\` or`,
    '// the prepublishOnly hook (which runs on every npm publish).',
    '',
  ].join('\n');
  const body = spec.renderBody({
    numbers: Array.from(rawBytes).join(', '),
    fingerprint,
    knownFingerprintsLiteral: JSON.stringify(known, null, 2),
  });
  return { text: `${header}\n${body}`, fingerprint };
}

/**
 * Verify without writing. Returns `{ ok, code, message }`; `code` is the process exit
 * status the CLI uses (0 ok, 2 pem missing/unparseable, 3 unknown fingerprint,
 * 4 generated file missing, 5 generated file out of sync).
 */
export function checkPubkeyBundle(spec) {
  const pemAbs = resolve(REPO_ROOT, spec.pem);
  const outAbs = resolve(REPO_ROOT, spec.out);
  if (!existsSync(pemAbs)) return { ok: false, code: 2, message: `pem file does not exist at ${spec.pem}. ${spec.missingPemHelp}` };
  let rendered;
  try {
    rendered = renderPubkeyModule(spec);
  } catch (err) {
    return { ok: false, code: 2, message: `failed to parse ${spec.pem}: ${err.message}` };
  }
  if (!spec.knownFingerprints.has(rendered.fingerprint)) {
    return {
      ok: false,
      code: 3,
      message:
        `pubkey RAW-bytes sha256 ${rendered.fingerprint} is not in KNOWN_PUBKEY_FINGERPRINTS of ${spec.script}. ` +
        'Either an unauthorized key change, or a rotation that did not append the new fingerprint — commit BOTH in one commit.',
    };
  }
  if (!existsSync(outAbs)) return { ok: false, code: 4, message: `generated file does not exist at ${spec.out}. Run \`node ${spec.script}\`.`, rendered };
  if (readFileSync(outAbs, 'utf-8') !== rendered.text) {
    return { ok: false, code: 5, message: `${spec.out} is out of sync with ${spec.pem}. Run \`node ${spec.script}\` to regenerate.`, rendered };
  }
  return { ok: true, code: 0, message: `${spec.out} is up to date (fingerprint ${rendered.fingerprint.slice(0, 16)}...)`, rendered };
}

/** CLI entry: `--check` verifies; otherwise writes only when the bytes differ. */
export function runPubkeyBundleCli(spec, argv = process.argv.slice(2)) {
  const res = checkPubkeyBundle(spec);
  if (argv.includes('--check') || res.ok || res.code < 4) {
    (res.ok ? console.log : console.error)(`${spec.script}${argv.includes('--check') ? ' --check' : ''}: ${res.ok ? 'OK — ' : 'error: '}${res.message}`);
    if (!res.ok) process.exit(res.code);
    return;
  }
  writeFileSync(resolve(REPO_ROOT, spec.out), res.rendered.text, 'utf-8');
  console.log(`${spec.script}: wrote ${spec.out} (fingerprint ${res.rendered.fingerprint.slice(0, 16)}...)`);
}

/** True when the calling module is the process entry point (not imported by a test). */
export function isMain(importMetaUrl) {
  return Boolean(process.argv[1]) && importMetaUrl === pathToFileURL(resolve(process.argv[1])).href;
}
